package pl.srgmobile.classic;
import android.content.*;
import android.media.*;
import android.os.*;
import android.webkit.JavascriptInterface;
import org.json.*;
import java.util.concurrent.*;

/** Native stream player, independent from WebView and BLE, with explicit user start. */
final class InternetRadio {
 private static InternetRadio instance;
 static synchronized InternetRadio get(Context context){if(instance==null)instance=new InternetRadio(context.getApplicationContext());return instance;}
 private final Context context;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private final SharedPreferences prefs;private final AudioManager audio;private final AudioFocusRequest focus;
 private MediaPlayer player;private volatile JSONArray results=new JSONArray();private volatile String status="Radio wyłączone",station="";private volatile boolean searching=false,playing=false,wanted=false;private boolean prepared=false,focusPaused=false;private int generation=0,fade=0;private float lastGain=0;
 private InternetRadio(Context c){context=c;prefs=c.getSharedPreferences("internet-radio",0);audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);station=prefs.getString("name","");focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setWillPauseWhenDucked(true).setOnAudioFocusChangeListener(change->ui.post(()->focusChanged(change)),ui).build();SpeechMix.listen(speaking->{if(Looper.myLooper()==ui.getLooper())speechChanged(speaking);else ui.post(()->speechChanged(speaking));});IntentFilter noisy=new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY);c.registerReceiver(new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){stopWithStatus("Odłączono wyjście audio - radio zatrzymane");}},noisy);}
 private void speechChanged(boolean speaking){if(!speaking&&wanted&&prepared&&focusPaused){if(gainFocus()){focusPaused=false;try{player.start();playing=true;}catch(Exception ignored){}}}volume(!speaking);}
 int generation(){return generation;}
 @JavascriptInterface public String state(){try{return new JSONObject().put("status",status).put("station",station).put("playing",playing).put("wanted",wanted).put("searching",searching).put("results",results).put("volume",prefs.getInt("volume",50)).put("duck",prefs.getInt("duck",10)).put("speaking",SpeechMix.active()).put("saved",!prefs.getString("url","").isEmpty()).toString();}catch(Exception e){return "{}";}}
 @JavascriptInterface public void search(String name,boolean poland){if(searching)return;final String query=name==null?"":name.trim();if(query.length()>100)return;searching=true;status="Szukam stacji…";worker.execute(()->{try{results=RadioStations.search(query,poland);status=results.length()==0?"Brak wyników. Zmień nazwę lub kraj.":"Wybierz stację ("+results.length()+")";}catch(Exception e){status=e.getMessage();}finally{searching=false;}});}
 @JavascriptInterface public void play(String id){JSONObject selected=null;for(int i=0;i<results.length();i++){JSONObject s=results.optJSONObject(i);if(s!=null&&s.optString("id").equals(id)){selected=s;break;}}if(selected==null)return;JSONObject s=selected;ui.post(()->start(s.optString("url"),s.optString("name"),s.optString("id")));}
 @JavascriptInterface public void playSaved(){ui.post(()->start(prefs.getString("url",""),prefs.getString("name",""),prefs.getString("id","")));}
 @JavascriptInterface public void stop(){ui.post(()->stopWithStatus("Radio zatrzymane"));}
 @JavascriptInterface public void configure(int volume,int duck){prefs.edit().putInt("volume",Math.max(0,Math.min(100,volume))).putInt("duck",Math.max(0,Math.min(100,duck))).apply();ui.post(()->volume(false));}
 private boolean gainFocus(){int mode=audio.getMode();return mode!=AudioManager.MODE_IN_CALL&&mode!=AudioManager.MODE_IN_COMMUNICATION&&mode!=AudioManager.MODE_RINGTONE&&audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}
 private void start(String url,String name,String id){if(!RadioStations.streamUrl(url)){status="Wybierz najpierw stację";return;}stopInternal();wanted=true;station=name;status="Łączenie: "+name;int serial=++generation;try{context.startForegroundService(new Intent(context,InternetRadioService.class));MediaPlayer mp=new MediaPlayer();player=mp;mp.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());mp.setWakeMode(context,PowerManager.PARTIAL_WAKE_LOCK);mp.setDataSource(url);if(!new AnnouncementOutput(context).apply(mp))throw new IllegalStateException("Wybrane wyjście Bluetooth nie jest połączone");mp.setOnPreparedListener(p->{if(serial!=generation||player!=p)return;prepared=true;if(!SpeechMix.active()&&!gainFocus()){stopWithStatus("Radio zatrzymane - rozmowa lub inne audio");return;}focusPaused=SpeechMix.active();volume(false);p.start();playing=true;status="Odtwarzanie: "+station;});mp.setOnErrorListener((p,w,e)->{if(player==p)stopWithStatus("Nie można odtworzyć stacji. Sprawdź internet lub wybierz inny strumień.");return true;});mp.setOnCompletionListener(p->{if(player==p)stopWithStatus("Stacja zakończyła nadawanie. Włącz ponownie lub wybierz inną.");});mp.prepareAsync();prefs.edit().putString("url",url).putString("name",name).putString("id",id).apply();worker.execute(()->RadioStations.click(id));ui.postDelayed(()->{if(serial==generation&&wanted&&!prepared)stopWithStatus("Przekroczono czas łączenia ze stacją. Spróbuj ponownie.");},25000);}catch(Exception e){stopWithStatus("Radio: "+e.getMessage());}}
 private void focusChanged(int change){if(!wanted||player==null)return;if(change==AudioManager.AUDIOFOCUS_LOSS){stopWithStatus("Radio zatrzymane przez inne audio");return;}int mode=audio.getMode();if(mode==AudioManager.MODE_IN_CALL||mode==AudioManager.MODE_IN_COMMUNICATION||mode==AudioManager.MODE_RINGTONE){try{if(prepared)player.pause();}catch(Exception ignored){}playing=false;focusPaused=true;status="Radio wstrzymane na czas rozmowy";return;}if(change==AudioManager.AUDIOFOCUS_GAIN){focusPaused=false;if(prepared)try{player.start();playing=true;status="Odtwarzanie: "+station;volume(true);}catch(Exception e){stopWithStatus("Nie wznowiono stacji");}}else if(change<0){if(SpeechMix.active()){volume(false);return;}if(change==AudioManager.AUDIOFOCUS_LOSS){stopWithStatus("Radio zatrzymane przez inne audio");return;}try{if(prepared)player.pause();}catch(Exception ignored){}playing=false;focusPaused=true;status="Radio wstrzymane - rozmowa lub inne audio";}}
 private void volume(boolean smooth){int serial=++fade;float target=SpeechMix.gain(prefs.getInt("volume",50),prefs.getInt("duck",10),SpeechMix.active());if(player==null)return;if(!smooth||target<=lastGain){setGain(target);return;}float from=lastGain;for(int i=1;i<=8;i++){final float value=from+(target-from)*i/8;ui.postDelayed(()->{if(serial==fade)setGain(value);},i*60L);}}
 private void setGain(float v){if(player!=null)try{player.setVolume(v,v);lastGain=v;}catch(Exception ignored){}}
 private void stopInternal(){wanted=false;playing=false;prepared=false;focusPaused=false;generation++;fade++;if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}audio.abandonAudioFocusRequest(focus);}
 void stopWithStatus(String message){stopInternal();status=message;context.stopService(new Intent(context,InternetRadioService.class));}
 void serviceEnded(int serial){ui.post(()->{if(wanted&&generation==serial)stopWithStatus("Radio zatrzymane");});}
}
